<?php
namespace App\Http\Controllers\Api;
use App\Models\Reservation;
use App\Models\Visit;
use Illuminate\Http\Request;
use Illuminate\Support\Str;
class ReservationController { use Support; public function index() { return Reservation::with(['guest','employee'])->latest()->get(); } public function show(Reservation $reservation) { return $reservation->load(['guest','employee']); } public function store(Request $r) { $slot = collect($this->slots((int)$r->employee_id, $r->date))->firstWhere('start', $r->start); abort_unless($slot && $slot['available'], 409, 'Slot tidak tersedia'); $guest = $this->guest($r->all()); $id = (Reservation::max('id') ?? 0) + 1; $reservation = Reservation::create(['guest_id'=>$guest->id,'employee_id'=>$r->employee_id,'code'=>'RSV-'.str_replace('-','',$r->date).'-'.str_pad($id,4,'0',STR_PAD_LEFT),'token'=>Str::random(64),'date'=>$r->date,'start_time'=>$r->start,'end_time'=>$r->end,'purpose'=>$r->purpose,'status'=>'CONFIRMED']); return ['reservation'=>$reservation,'guest'=>$guest]; } public function cancel(Reservation $reservation) { $reservation->update(['status'=>'CANCELLED']); return $reservation; } public function checkIn(Reservation $reservation) { abort_unless(in_array($reservation->status, ['PENDING','CONFIRMED']), 409, 'Reservasi tidak valid untuk check-in'); $reservation->update(['status'=>'CHECKED_IN']); $visit = Visit::create(['guest_id'=>$reservation->guest_id,'employee_id'=>$reservation->employee_id,'purpose'=>$reservation->purpose,'visit_date'=>now()->toDateString(),'check_in_at'=>now(),'visit_type'=>'reservation','status'=>'CHECKED_IN']); return ['reservation'=>$reservation,'visit'=>$visit]; } }
